import type {
  BenchPlan,
  ComponentName,
  ImplementationName,
  ScenarioAction,
  ScenarioName,
} from './types';

const ACTIONS: readonly ScenarioAction[] = [
  'mount',
  'update',
  'memory',
  'leak',
];

/**
 * Components that carry their name in the scenario cell. `switch` is absent:
 * its cells are the bare action names, which existing results files use.
 */
const SUFFIXED_COMPONENTS: readonly Exclude<ComponentName, 'switch'>[] = [
  // @generated by scripts/gen-registry.mjs (region: suffixed-components) - do not edit; run bun run regen
  'slider',
  'button',
  'progress',
  'segmented-control',
  'date-picker',
  'picker',
  'menu',
  'text-field',
  'form',
  'icon-button',
  'button-group',
  'stepper',
  'list-item',
  // @end-generated
];

const IMPLEMENTATIONS: readonly ImplementationName[] = [
  'rn-core',
  'expo-ui-host-per-control',
  'expo-ui-shared-host',
  'nitro-ui',
  // The library's own controls in one shared composition (`Host`).
  'nitro-ui-host',
];

/**
 * Split `update.slider` into its action and component. A bare action is a
 * `switch` cell. Returns null for anything else, so an unknown cell fails the
 * launch instead of measuring the wrong control.
 */
function splitScenario(value: string): [ScenarioAction, ComponentName] | null {
  const dot = value.indexOf('.');
  if (dot === -1) {
    return (ACTIONS as readonly string[]).includes(value)
      ? [value as ScenarioAction, 'switch']
      : null;
  }
  const action = value.slice(0, dot);
  const component = value.slice(dot + 1);
  if (
    !(ACTIONS as readonly string[]).includes(action) ||
    !(SUFFIXED_COMPONENTS as readonly string[]).includes(
      component as Exclude<ComponentName, 'switch'>
    )
  ) {
    return null;
  }
  return [action as ScenarioAction, component as ComponentName];
}

function isImplementation(value: string): value is ImplementationName {
  return (IMPLEMENTATIONS as readonly string[]).includes(value);
}

/**
 * `scenario:implementation` pairs whose commit changes no native prop, so Fabric
 * creates no mounting transaction and the probe has no mount to wait for: the
 * `rn-core` arm has no value to flip for these components.
 */
const NO_MOUNT_SIGNAL: readonly string[] = [
  'update.slider:rn-core',
  'update.progress:rn-core',
];

// This file must not import the probe: the probe creates its native object at
// import time, and a plan has to parse, or be rejected, before that.
export const MOUNT_TIMEOUT_FLAG = 'mountTimeout';
export const PRESENTED_TIMEOUT_FLAG = 'presentedTimeout';

export type BenchPlatform = 'ios' | 'android';

/**
 * How long a launch waits for each native signal before calling it missing.
 *
 * `scripts/bench/lib.mjs` restates these defaults, because it cannot import
 * TypeScript, and the two must match. A launch that overrides a timeout is
 * diagnostic, not baseline material: which samples arrive moves the median.
 */
export interface BenchTimeouts {
  /** Default wait for the mount signal. */
  mountTimeoutMs: number;
  /** Default wait for the presenting frame. */
  presentedTimeoutMs: number;
  /** The native presentation backstop, so a requested wait can stay below it. */
  presentationCeilingMs: number;
  /** The longest wait this platform may be asked for, one tick below its backstop. */
  maxRequestedTimeoutMs: number;
}

export const BENCH_DEFAULT_TIMEOUTS: Record<BenchPlatform, BenchTimeouts> = {
  ios: {
    mountTimeoutMs: 1500,
    // Above the slowest first frame the heaviest reference cells present on the
    // simulator (about 3 s), so they do not lose presenting samples.
    presentedTimeoutMs: 8000,
    presentationCeilingMs: 90_000,
    maxRequestedTimeoutMs: 80_000,
  },
  android: {
    mountTimeoutMs: 1500,
    // Short on purpose: the Android cells that lose presenting samples never draw
    // a frame at all, so a longer wait only inflates the CPU rows around it.
    presentedTimeoutMs: 2000,
    // Must match `PRESENTATION_CEILING_MS` in `HybridBenchProbe.kt`.
    presentationCeilingMs: 2_000,
    // Below the backstop: a wait at or above it would be answered by the native
    // timer and recorded as a timeout the run never asked for.
    maxRequestedTimeoutMs: 1_900,
  },
};

export function defaultTimeoutsFor(platform: BenchPlatform): BenchTimeouts {
  const defaults = BENCH_DEFAULT_TIMEOUTS[platform];
  if (defaults == null) {
    throw new Error(
      `no default signal timeouts for platform "${String(platform)}" (known: ${Object.keys(
        BENCH_DEFAULT_TIMEOUTS
      ).join(', ')})`
    );
  }
  return defaults;
}

/**
 * Parse the `scenario:implementation:N[:flags]` launch argument, where `flags` is a
 * comma-separated list of:
 *
 * - `marks` - ask the runtime for its own native perf marks (`bun bench --perf-marks`);
 * - `presentedTimeout=<ms>` - how long to wait for the presenting frame;
 * - `mountTimeout=<ms>` - how long to wait for the mount signal.
 *
 * The flags travel in the launch argument because a release build has no
 * environment. `platform` is passed in because the defaults and the cap on a
 * requested wait differ per platform and this file does not import `react-native`.
 *
 * Returns null for an unconfigured launch, which renders the idle screen.
 */
export function parsePlan(
  raw: string,
  platform: BenchPlatform
): BenchPlan | null {
  if (raw.length === 0) {
    return null;
  }
  const parts = raw.split(':');
  const [scenario, implementation, count, flags] = parts;
  const halves = scenario == null ? null : splitScenario(scenario);
  if (
    (parts.length !== 3 && parts.length !== 4) ||
    scenario == null ||
    implementation == null ||
    count == null ||
    halves === null ||
    !isImplementation(implementation)
  ) {
    throw new Error(
      `NITRO_BENCH unparseable plan "${raw}" (expected scenario:implementation:N, ` +
        `got scenarios ${ACTIONS.map((action) =>
          [action, ...SUFFIXED_COMPONENTS.map((c) => `${action}.${c}`)].join(
            '|'
          )
        ).join('|')} and implementations ${IMPLEMENTATIONS.join('|')})`
    );
  }
  const n = Number(count);
  if (!Number.isInteger(n) || n < 0) {
    throw new Error(
      `NITRO_BENCH plan "${raw}" has a non-negative integer count`
    );
  }
  const {
    mountTimeoutMs: defaultMount,
    presentedTimeoutMs: defaultPresented,
    maxRequestedTimeoutMs: maxMs,
  } = defaultTimeoutsFor(platform);
  let perfMarks = false;
  let mountTimeoutMs = defaultMount;
  let presentedTimeoutMs = defaultPresented;
  for (const flag of (flags ?? '').split(',').map((part) => part.trim())) {
    if (flag === '') {
      continue;
    }
    if (flag === 'marks') {
      perfMarks = true;
      continue;
    }
    const [name, value, extra] = flag.split('=');
    const ms = Number(value);
    if (
      extra != null ||
      value == null ||
      value === '' ||
      !Number.isFinite(ms) ||
      ms < 1 ||
      ms > maxMs
    ) {
      throw new Error(
        `NITRO_BENCH plan "${raw}" has an unknown or malformed flag "${flag}" ` +
          `(known: marks, ${MOUNT_TIMEOUT_FLAG}=<1..${String(maxMs)}>, ` +
          `${PRESENTED_TIMEOUT_FLAG}=<1..${String(maxMs)}>)`
      );
    }
    if (name === MOUNT_TIMEOUT_FLAG) {
      mountTimeoutMs = ms;
    } else if (name === PRESENTED_TIMEOUT_FLAG) {
      presentedTimeoutMs = ms;
    } else {
      throw new Error(
        `NITRO_BENCH plan "${raw}" has an unknown flag "${name}" ` +
          `(known: marks, ${MOUNT_TIMEOUT_FLAG}, ${PRESENTED_TIMEOUT_FLAG})`
      );
    }
  }
  const [action, component] = halves;
  return {
    scenario: scenario as ScenarioName,
    action,
    component,
    implementation,
    n,
    mountSignal: !NO_MOUNT_SIGNAL.includes(`${scenario}:${implementation}`),
    perfMarks,
    mountTimeoutMs,
    presentedTimeoutMs,
  };
}
